ALTER TABLE "market_visits" ADD CONSTRAINT "market_visits_market_id_markets_id_fk" FOREIGN KEY ("market_id") REFERENCES "public"."markets"("id") ON DELETE restrict ON UPDATE no action;--> statement-breakpoint
CREATE INDEX "market_visits_visit_date_idx" ON "market_visits" USING btree ("visit_date");--> statement-breakpoint
