-- Hand-edited: a visit is a person's (151-3 "관리자와 봇의 조회도 남기지 않는다"): 0059's function
-- refuses the 운영 마켓메이커 a row, whoever writes, and 0043's refuses a closed account's — a request
-- that passed the session check just before a closure committed takes no row (its profile FOR KEY
-- SHARE waits for the closure in flight). The API answers the latter as the session that ended
-- (CLOSED_ACCOUNT_ROW_TRIGGERS). The admin exclusion is the writer's (`recordMarketVisit`, by the
-- grant and revoke records — 96-10), not a trigger's.
CREATE TRIGGER market_visits_human_account
  BEFORE INSERT ON "market_visits"
  FOR EACH ROW EXECUTE FUNCTION refuse_operating_account_rows('user_id');--> statement-breakpoint
CREATE TRIGGER market_visits_open_account
  BEFORE INSERT ON "market_visits"
  FOR EACH ROW EXECUTE FUNCTION refuse_closed_account_rows();--> statement-breakpoint
-- Hand-edited: the collection's start, the instant this migration runs (151-4 "배포되면 바로").
INSERT INTO "market_visit_collection" DEFAULT VALUES;--> statement-breakpoint
-- Hand-edited: a visit row is never changed, and buddha_app inserts only its account and market —
-- the date is always the database's. It keeps SELECT (the metrics, ON CONFLICT's target) and
-- DELETE (the retention purge). With no UPDATE on any column it can take no row lock on the table
-- (FOR UPDATE, FOR KEY SHARE need one), which the purge does not need. The collection marker is
-- read only.
REVOKE INSERT, UPDATE ON TABLE "market_visits" FROM buddha_app;--> statement-breakpoint
GRANT INSERT ("user_id", "market_id") ON TABLE "market_visits" TO buddha_app;--> statement-breakpoint
REVOKE INSERT, UPDATE, DELETE ON TABLE "market_visit_collection" FROM buddha_app;
